p=argparse.ArgumentParser();p.add_argument('--source-root',required=True);p.add_argument('--env-file',required=True);p.add_argument('--expected-head',default='822c15785449b6c1cef699f6fd4d8e1f5483bd5e');a=p.parse_args();src=pathlib.Path(a.source_root).resolve();head=subprocess.check_output(['git','-C',str(src),'rev-parse','HEAD'],text=True).strip();assert head==a.expected_head,'Select the exact tested candidate explicitly';env=dict(os.environ)
for k in list(env):
 if k.startswith(('MULTICA_','OPENAI_','ANTHROPIC_','CLAUDE_','E2E_','COLLABORATION_')):env.pop(k,None)
